// Production-deploy guard: a tool call matching a production-deploy pattern
// is put to the native ask dialog, whatever the permission mode allowed.
// Additive to any shell hook or daemon guard doing the same; a deny beneath
// stays a deny.
//
// Matching is a port of the daemon's approval-rule matcher: `Tool` or
// `Tool(argGlob)`; the tool part exact, the glob over the tool's argument
// string, case-insensitive, `*` any run of characters and nothing else
// special. The shipped list is hooks/patterns/prod.json; the project's own
// .claude/project.json approvals.prodDeployPatterns are added to it.

import { type ProdPattern, compileProd } from './patterns'
import type { ProjectConfig } from './roots'

/** `*` matches any run of characters (including `/`, spaces); the rest is literal. */
export const globMatch = (pattern: string, s: string): boolean => {
  const parts = pattern.split('*')
  if (parts.length === 1) return s === pattern
  const first = parts[0] ?? ''
  if (!s.startsWith(first)) return false
  let rest = s.slice(first.length)
  for (const mid of parts.slice(1, -1)) {
    if (mid === '') continue
    const i = rest.indexOf(mid)
    if (i < 0) return false
    rest = rest.slice(i + mid.length)
  }
  const last = parts[parts.length - 1] ?? ''
  return last === '' || rest.endsWith(last)
}

// The tool → argument-field allow-list; a tool not listed has no argument
// string, so a Tool(argGlob) pattern never matches it.
const ARG_FIELDS: Readonly<Record<string, string>> = {
  Bash: 'command',
  Read: 'file_path',
  Write: 'file_path',
  Edit: 'file_path',
  WebFetch: 'url',
  Glob: 'pattern',
  Grep: 'pattern',
}

export const argOf = (tool: string, input: unknown): string | undefined => {
  const field = ARG_FIELDS[tool]
  if (field === undefined || typeof input !== 'object' || input === null) return undefined
  const v = (input as Readonly<Record<string, unknown>>)[field]
  return typeof v === 'string' && v !== '' ? v : undefined
}

export const matchProd = (
  patterns: readonly ProdPattern[],
  tool: string,
  input: unknown,
): ProdPattern | undefined => {
  const arg = argOf(tool, input)?.toLowerCase()
  return patterns.find(p => p.tool === tool && (p.inner === undefined || (arg !== undefined && globMatch(p.inner, arg))))
}

/** The project's own approvals.prodDeployPatterns, added to the shipped list. */
export const projectProdPatterns = (project: ProjectConfig | undefined): ProdPattern[] => {
  const approvals = project?.json.approvals
  if (typeof approvals !== 'object' || approvals === null) return []
  return compileProd((approvals as Readonly<Record<string, unknown>>).prodDeployPatterns)
}

export const prodReason = (hit: ProdPattern): string =>
  `guard-pack: production deploy (matches ${hit.source}); confirm it yourself`

files.hooks/redaction.ts:
// Redaction: every secret-shaped value inside a tool_result block becomes
// [REDACTED:<rule>] before the row is stored and before the model reads it.
// Rows without a tool_result block, and every other block of a row, are
// handed on untouched.

import type { SecretRule } from './patterns'

export const MARK_PREFIX = '[REDACTED:'

/** Applies every rule in order; returns the new text and how many values it masked. */
export const redactText = (text: string, rules: readonly SecretRule[]): { text: string; count: number } => {
  let count = 0
  let out = text
  for (const rule of rules) {
    const keepsPrefix = rule.replace.includes('$1')
    out = out.replace(rule.re, (match: string, ...rest: unknown[]) => {
      const prefix = keepsPrefix && typeof rest[0] === 'string' ? rest[0] : ''
      if (match.slice(prefix.length).startsWith(MARK_PREFIX)) return match
      count++
      // replacer functions, so a `$` inside the kept prefix is never read as a pattern
      return rule.replace.replace('{mark}', () => `${MARK_PREFIX}${rule.name}]`).replace('$1', () => prefix)
    })
  }
  return { text: out, count }
}

type Block = Readonly<Record<string, unknown>>

const redactResultContent = (
  content: unknown,
  rules: readonly SecretRule[],
): { content: unknown; count: number } => {
  if (typeof content === 'string') {
    const r = redactText(content, rules)
    return { content: r.text, count: r.count }
  }
  if (!Array.isArray(content)) return { content, count: 0 }
  let count = 0
  const next = content.map((b: unknown) => {
    const block = b as Block
    if (typeof block !== 'object' || block === null || block.type !== 'text' || typeof block.text !== 'string') {
      return b
    }
    const r = redactText(block.text, rules)
    count += r.count
    return r.count === 0 ? b : { ...block, text: r.text }
  })
  return { content: count === 0 ? content : next, count }
}

/** The row's blocks with tool_result contents redacted; other blocks as they were. */
export const redactBlocks = (
  blocks: readonly unknown[],
  rules: readonly SecretRule[],
): { blocks: unknown[]; count: number } => {
  let count = 0
  const out = blocks.map((b: unknown) => {
    const block = b as Block
    if (typeof block !== 'object' || block === null || block.type !== 'tool_result') return b
    const r = redactResultContent(block.content, rules)
    count += r.count
    return r.count === 0 ? b : { ...block, content: r.content }
  })
  return { blocks: out, count }
}

export const hasToolResult = (content: unknown): content is readonly unknown[] =>
  Array.isArray(content) &&
  content.some(b => typeof b === 'object' && b !== null && (b as Block).type === 'tool_result')

export const statusLine = (total: number): string =>
  `guard: ${total} secret${total === 1 ? '' : 's'} redacted`

